5: /// <summary>
6: /// TR-MCP-NUKE-019 AC-6 (hostile validation finding R8B-F3): starts the process of a temporary instance, or of a REPL
7: /// child started against one, with an environment no inherited product setting reaches. Linked into every project
8: /// whose integration cases start such a process (the stdio host case of QBrainAi.Support.Mcp.Tests, ScratchQBrainAi and
9: /// its REPL children); the rule itself is the pure <see cref="TemporaryInstanceChecks"/> builder and check, proved in
10: /// QBrainAi.Repl.Core.Tests.
11: /// </summary>
12: internal static class OwnedInstanceProcess
13: {
14:     /// <summary>
15:     /// Replaces the environment of <paramref name="startInfo"/> with the one
16:     /// <see cref="TemporaryInstanceChecks.BuildOwnedInstanceEnvironment"/> builds from the inherited environment and
17:     /// <paramref name="settings"/>, and throws before the process starts when
18:     /// <see cref="TemporaryInstanceChecks.CheckOwnedInstanceEnvironment"/> refuses it.
19:     /// </summary>
20:     /// <param name="startInfo">The start information whose environment is replaced.</param>
21:     /// <param name="settings">The process's own variables.</param>
22:     /// <param name="ownedRoot">The temporary instance's root folder.</param>
23:     internal static void ApplyOwnedEnvironment(ProcessStartInfo startInfo, IReadOnlyDictionary<string, string> settings, string ownedRoot)
24:     {
25:         ArgumentNullException.ThrowIfNull(startInfo);
26:         ReplaceEnvironment(startInfo.Environment, settings, ownedRoot);
27:     }
28: 
29:     /// <summary>
30:     /// FR-MCP-TESTRESOURCE-001 ac-4: validates an explicit environment before changing its target dictionary.
31:     /// The process adapter uses this same boundary, so unit tests need no ambient process environment.
32:     /// </summary>
33:     /// <param name="environment">The inherited values to replace only after validation succeeds.</param>
34:     /// <param name="settings">The owned instance's values.</param>
35:     /// <param name="ownedRoot">The absolute owned data root.</param>
36:     internal static void ReplaceEnvironment(IDictionary<string, string?> environment, IReadOnlyDictionary<string, string> settings, string ownedRoot)
37:     {
38:         ArgumentNullException.ThrowIfNull(environment);
39:         var inherited = new Dictionary<string, string?>(StringComparer.Ordinal);
40:         foreach (var (key, value) in environment)
41:         {
42:             inherited[key] = value;
43:         }
44: 
45:         var child = TemporaryInstanceChecks.BuildOwnedInstanceEnvironment(inherited, settings);
46:         var violation = TemporaryInstanceChecks.CheckOwnedInstanceEnvironment(child, settings, ownedRoot);
47:         if (violation is not null)
48:         {
49:             throw new InvalidOperationException(violation);
50:         }
51: 
52:         environment.Clear();
53:         foreach (var (key, value) in child)
54:         {
55:             environment[key] = value;
56:         }
57:     }
58: }
