414:     {
415:         using var http = new HttpClient { BaseAddress = new Uri(baseUrl, UriKind.Absolute) };
416:         using var timeout = new CancellationTokenSource(ServerHealthTimeout);
417:         while (!timeout.IsCancellationRequested)
418:         {
419:             if (_process is { HasExited: true })
420:             {
421:                 // Drain the redirected output so the message and the restart check see all of it.
422:                 await _process.WaitForExitAsync().ConfigureAwait(false);
423:                 throw new InvalidOperationException(
