90:     /// <summary>The unit texts on disk when the failure happens and the texts the archive holds.</summary>
91:     /// <param name="Fragment">The unit file text.</param>
92:     /// <param name="DropIn">The drop-in text, or null when the unit has none.</param>
93:     internal sealed record UnitTexts(string Fragment, string? DropIn);
94: 
95:     /// <summary>What a recovery leaves: the final unit texts and the recovery events in order.</summary>
96:     /// <param name="Texts">The unit texts after the recovery.</param>
97:     /// <param name="Events">The recovery events, starting with the stop.</param>
98:     internal sealed record RecoveryOutcome(UnitTexts Texts, IReadOnlyList<string> Events);
99: 
100:     /// <summary>A recovery as the contract sees it: the texts at the failure, the archived texts and whether the unit
101:     /// names the legacy apphost.</summary>
102:     internal delegate RecoveryOutcome Recovery(UnitTexts atFailure, UnitTexts archived, bool namesLegacy);
103: 
104:     /// <summary>The texts on disk when the update fails: the success path has retargeted a legacy unit before the health
105:     /// check, never before the runtime configuration copy.</summary>
106:     /// <param name="row">The contract row.</param>
107:     /// <returns>The texts at the failure.</returns>
108:     internal static UnitTexts AtFailure(Row row)
109:         => row.Failure == FailurePoint.Health && row.NamesLegacy
110:             ? new(row.ArchivedFragment.Replace(Legacy, Current, StringComparison.Ordinal), row.ArchivedDropIn?.Replace(Legacy, Current, StringComparison.Ordinal))
111:             : new(row.ArchivedFragment, row.ArchivedDropIn);
112: 
113:     /// <summary>Independent reference recovery: stop, restore the archive, then retarget the legacy name and reload only
114:     /// when a file changed.</summary>
115:     private static RecoveryOutcome ReferenceRecovery(UnitTexts atFailure, UnitTexts archived, bool namesLegacy)
116:     {
117:         var events = new List<string> { "stop", "restore" };
118:         var fragment = archived.Fragment;
119:         var dropIn = archived.DropIn;
120:         if (namesLegacy)
121:         {
122:             var newFragment = fragment.Replace(Legacy, Current, StringComparison.Ordinal);
123:             var newDropIn = dropIn?.Replace(Legacy, Current, StringComparison.Ordinal);
124:             if (newFragment != fragment || newDropIn != dropIn) events.Add("daemon-reload");
125:             fragment = newFragment;
126:             dropIn = newDropIn;
127:         }
128:         return new(new(fragment, dropIn), events);
129:     }
130: 
131:     /// <summary>Wrong recoveries the rows must reject; the first is the failure path the redeploy met.</summary>
132:     internal static readonly (string Name, Recovery Recovery)[] WrongRecoveries =
133:     [
134:         ("restores and stops there", (_, archived, _) => new(archived, ["stop", "restore"])),
135:         ("retargets but never reloads", (atFailure, archived, legacy) =>
136:         {
137:             var outcome = ReferenceRecovery(atFailure, archived, legacy);
138:             return new(outcome.Texts, outcome.Events.Where(item => item != "daemon-reload").ToArray());
139:         }),
140:         ("retargets before the restore", (atFailure, archived, legacy) =>
141:         {
142:             var events = new List<string> { "stop" };
143:             if (legacy) events.Add("daemon-reload");
144:             events.Add("restore");
145:             return new(archived, events);
146:         }),
147:         ("retargets only the unit file", (atFailure, archived, legacy) =>
148:         {
149:             if (!legacy) return new(archived, ["stop", "restore"]);
150:             var fragment = archived.Fragment.Replace(Legacy, Current, StringComparison.Ordinal);
151:             var events = fragment != archived.Fragment ? new[] { "stop", "restore", "daemon-reload" } : new[] { "stop", "restore" };
152:             return new(new(fragment, archived.DropIn), events);
153:         }),
154:         ("reloads even when nothing changed", (atFailure, archived, legacy) =>
155:         {
156:             var outcome = ReferenceRecovery(atFailure, archived, legacy);
157:             return outcome.Events.Contains("daemon-reload") ? outcome : new(outcome.Texts, ["stop", "restore", "daemon-reload"]);
158:         }),
159:         ("skips the restore", (atFailure, _, legacy) =>
160:         {
161:             var fragment = legacy ? atFailure.Fragment.Replace(Legacy, Current, StringComparison.Ordinal) : atFailure.Fragment;
162:             var dropIn = legacy ? atFailure.DropIn?.Replace(Legacy, Current, StringComparison.Ordinal) : atFailure.DropIn;
163:             var events = legacy ? new[] { "stop", "daemon-reload" } : new[] { "stop" };
164:             return new(new(fragment, dropIn), events);
165:         }),
166:     ];
167: 
168:     /// <summary>True when a recovery leaves exactly the row's expected unit texts and recovery events.</summary>
169:     /// <param name="recovery">The recovery under test.</param>
170:     /// <param name="row">The contract row.</param>
171:     /// <returns>Whether the recovery meets the row.</returns>
172:     internal static bool Meets(Recovery recovery, Row row)
173:     {
174:         var outcome = recovery(AtFailure(row), new(row.ArchivedFragment, row.ArchivedDropIn), row.NamesLegacy);
175:         return string.Equals(outcome.Texts.Fragment, row.ExpectedFragment, StringComparison.Ordinal)
176:             && string.Equals(outcome.Texts.DropIn, row.ExpectedDropIn, StringComparison.Ordinal)
177:             && outcome.Events.SequenceEqual(row.ExpectedRecovery, StringComparer.Ordinal);
178:     }
179: 
180:     /// <summary>The reference recovery meets every contract row (rows: <see cref="Rows"/>).</summary>
181:     [Fact]
182:     public void ReferenceRecovery_MeetsEveryRow()
183:     {
184:         foreach (var row in Rows)
185:             Assert.True(Meets(ReferenceRecovery, row), row.Name);
186:     }
187: 
188:     /// <summary>Each wrong recovery fails at least one contract row, so the rows discriminate (negative controls).</summary>
189:     /// <param name="index">The wrong recovery's position in <see cref="WrongRecoveries"/>.</param>
190:     [Theory]
191:     [InlineData(0)]
192:     [InlineData(1)]
193:     [InlineData(2)]
194:     [InlineData(3)]
195:     [InlineData(4)]
196:     [InlineData(5)]
197:     public void WrongRecovery_FailsAtLeastOneRow(int index)
198:     {
199:         var (name, recovery) = WrongRecoveries[index];
200:         Assert.Contains(Rows, row => !Meets(recovery, row));
201:         Assert.False(string.IsNullOrEmpty(name));
202:     }
203: 
204:     /// <summary>The failure path the redeploy met fails exactly the rows whose unit names the legacy apphost.</summary>
205:     [Fact]
206:     public void OldRecovery_FailsOnlyTheLegacyRows()
207:     {
208:         var failed = Rows.Where(row => !Meets(WrongRecoveries[0].Recovery, row)).Select(row => row.Name).ToArray();
209:         Assert.Equal(Rows.Where(row => row.NamesLegacy).Select(row => row.Name).ToArray(), failed);
210:     }
211: }

