168:     /// <summary>
169:     /// TR-MCP-NUKE-020 AC-5: whether a definition's class name is the named class, as the whole name or its last segment
170:     /// ('.' or '+' separated, '+' marking a nested class).
171:     /// </summary>
172:     /// <param name="className">The definition's TestMethod class name.</param>
173:     /// <param name="name">The class a group names.</param>
