1: [CmdletBinding()]
2: param(
3:     [ValidateSet('Read','Search','Files','Git','Analyze','Proof')][string]$Kind,
4:     [string[]]$Paths,
5:     [string]$Pattern,
6:     [string[]]$Arguments,
7:     [int]$Start = 1,
8:     [int]$Count = 0
9: )
10: $ErrorActionPreference = 'Stop'
11: $exitCode = 0
12: switch ($Kind) {
13:     'Read' {
14:         foreach ($path in $Paths) {
15:             $lines = [System.IO.File]::ReadAllLines($path)
16:             $end = if ($Count -gt 0) { [Math]::Min($lines.Length, $Start - 1 + $Count) } else { $lines.Length }
17:             Write-Output ('FILE=' + $path + '; Lines=' + $lines.Length)
18:             for ($index = $Start - 1; $index -lt $end; $index++) { Write-Output ('{0}: {1}' -f ($index + 1), $lines[$index]) }
19:         }
20:     }
21:     'Search' { & rg -n -- $Pattern @Paths; $exitCode = $LASTEXITCODE }
22:     'Files' { & rg --files @Arguments @Paths; $exitCode = $LASTEXITCODE }
23:     'Git' { & git --no-optional-locks @Arguments; $exitCode = $LASTEXITCODE }
24:     'Analyze' {
25:         foreach ($path in $Paths) {
26:             $parseTokens = $null
27:             $parseErrors = $null
28:             [System.Management.Automation.Language.Parser]::ParseFile($path, [ref]$parseTokens, [ref]$parseErrors) | Out-Null
29:             $issues = @(Invoke-ScriptAnalyzer -Path $path -Severity Warning,Error)
30:             if ($parseErrors.Count -gt 0 -or $issues.Count -gt 0) { $exitCode = 1 }
31:             [pscustomobject]@{ path=$path; parseErrors=@($parseErrors); analyzerIssues=$issues } | ConvertTo-Json -Depth 10
32:         }
33:     }
34:     'Proof' {
35:         $rollout = Get-ChildItem -LiteralPath '/home/sharpninja/.codex/sessions' -Recurse -File -Filter ('*' + $env:CODEX_THREAD_ID + '.jsonl') | Select-Object -First 1
36:         $proofs = @()
37:         $lineNumber = 0
38:         foreach ($line in [System.IO.File]::ReadLines($rollout.FullName)) {
39:             $lineNumber++
40:             $entry = $line | ConvertFrom-Json -Depth 100
41:             if ($entry.type -eq 'turn_context') {
42:                 $proofs += [pscustomobject]@{ line=$lineNumber; timestamp=$entry.timestamp; model=$entry.payload.model; effort=$entry.payload.effort; turnId=$entry.payload.turn_id; cwd=$entry.payload.cwd; collaborationMode=$entry.payload.collaboration_mode }
43:             }
44:         }
45:         $result = [pscustomobject]@{ threadId=$env:CODEX_THREAD_ID; rollout=$rollout.FullName; readUtc=[DateTime]::UtcNow.ToString('o'); turns=$proofs }
46:         $result | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath './docs/receipts/hv/hv-ug-r12-identity.json'
47:         $result | ConvertTo-Json -Depth 20
48:     }
49: }
50: [pscustomobject]@{ timestampUtc=[DateTime]::UtcNow.ToString('o'); timestampLocal=(Get-Date).ToString('s'); script=$PSCommandPath; kind=$Kind; paths=$Paths; pattern=$Pattern; arguments=$Arguments; start=$Start; count=$Count; exitCode=$exitCode } | ConvertTo-Json -Depth 10 -Compress | Add-Content -LiteralPath './docs/receipts/hv/hv-ug-r12-commands.jsonl'
51: exit $exitCode

