49:     /// <summary>Independent reference reader: a regular expression per line, values gathered per key in order.</summary>
50:     private static IReadOnlyDictionary<string, string> ReferenceReader(string output)
51:     {
52:         var gathered = new Dictionary<string, List<string>>(StringComparer.Ordinal);
53:         foreach (Match match in Regex.Matches(output, @"^(?<key>[^=\r\n]*)=(?<value>[^\r\n]*)\r?$", RegexOptions.Multiline | RegexOptions.CultureInvariant))
54:         {
55:             var key = match.Groups["key"].Value;
56:             if (!gathered.TryGetValue(key, out var values)) gathered[key] = values = [];
57:             values.Add(match.Groups["value"].Value);
58:         }
59:         return gathered.ToDictionary(pair => pair.Key, pair => string.Join(' ', pair.Value.Where(value => value.Length > 0)), StringComparer.Ordinal);
60:     }
61: 
62:     /// <summary>Wrong readers each contract row set must reject; the first is the defect the redeploy met.</summary>
63:     internal static readonly (string Name, PropertyReader Reader)[] WrongReaders =
64:     [
65:         ("throws on a repeated key", output => output.Split('\n').Where(line => line.Contains('=')).Select(line => line.Split('=', 2))
66:             .ToDictionary(pair => pair[0], pair => pair[1].TrimEnd('\r'), StringComparer.Ordinal)),
67:         ("keeps the first line", output => Gather(output, (old, _) => old)),
68:         ("keeps the last line", output => Gather(output, (_, value) => value)),
69:         ("keeps carriage returns", output => output.Split('\n').Where(line => line.Contains('=')).Select(line => line.Split('=', 2))
70:             .GroupBy(pair => pair[0]).ToDictionary(group => group.Key, group => string.Join(' ', group.Select(pair => pair[1]).Where(v => v.Length > 0)), StringComparer.Ordinal)),
71:         ("sorts repeated values", output => ReferenceReader(output).ToDictionary(pair => pair.Key,
72:             pair => string.Join(' ', pair.Value.Split(" /", StringSplitOptions.None).Select((part, i) => i == 0 ? part : "/" + part).Order(StringComparer.Ordinal)), StringComparer.Ordinal)),
73:         ("joins empty values too", output => output.Split('\n').Select(line => line.TrimEnd('\r')).Where(line => line.Contains('=')).Select(line => line.Split('=', 2))
74:             .GroupBy(pair => pair[0]).ToDictionary(group => group.Key, group => string.Join(' ', group.Select(pair => pair[1])), StringComparer.Ordinal)),
75:     ];
76: 
77:     /// <summary>Folds repeated keys with a chosen rule; used only by the wrong readers.</summary>
78:     private static IReadOnlyDictionary<string, string> Gather(string output, Func<string, string, string> fold)
79:     {
80:         var result = new Dictionary<string, string>(StringComparer.Ordinal);
81:         foreach (var line in output.Split('\n').Select(line => line.TrimEnd('\r')).Where(line => line.Contains('=')))
82:         {
83:             var pair = line.Split('=', 2);
84:             result[pair[0]] = result.TryGetValue(pair[0], out var old) ? fold(old, pair[1]) : pair[1];
85:         }
86:         return result;
87:     }
