1: /// <summary>
2: /// TR-MCP-NUKE-019: the provisioning download. The client has no total time limit; the request completes at the
3: /// response headers, the body is written to the destination as each read arrives (an unbuffered file), and the
4: /// inactivity limit restarts after every read, so a large release asset that keeps arriving finishes while a stalled
5: /// transfer fails. An error status or a stall fails with the URL in the message.
6: /// </summary>
7: sealed class ProvisioningDownload : IProvisioningDownload
8: {
9:     /// <summary>The inactivity limit the provisioning targets use (TR-MCP-NUKE-019: two minutes).</summary>
10:     internal static readonly TimeSpan DefaultInactivityLimit = TimeSpan.FromMinutes(2);
11: 
12:     /// <inheritdoc />
13:     public HttpClient CreateClient(HttpMessageHandler handler)
14:         => new(handler, disposeHandler: false) { Timeout = Timeout.InfiniteTimeSpan };
15: 
16:     /// <inheritdoc />
17:     public async Task DownloadAsync(
18:         HttpMessageHandler handler,
19:         Uri url,
20:         string destinationPath,
21:         TimeSpan inactivityLimit,
22:         CancellationToken cancellationToken)
23:     {
24:         using var client = CreateClient(handler);
25:         using var inactivity = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
26:         inactivity.CancelAfter(inactivityLimit);
27:         try
28:         {
29:             using var response = await client
30:                 .GetAsync(url, HttpCompletionOption.ResponseHeadersRead, inactivity.Token)
31:                 .ConfigureAwait(false);
32:             if (!response.IsSuccessStatusCode)
33:             {
34:                 throw new HttpRequestException(
35:                     $"Download of {url} failed: the server answered {(int)response.StatusCode} {response.ReasonPhrase}.",
36:                     inner: null,
37:                     response.StatusCode);
38:             }
39: 
40:             await using var source = await response.Content.ReadAsStreamAsync(inactivity.Token).ConfigureAwait(false);
41:             await using var target = new FileStream(
42:                 destinationPath,
43:                 FileMode.Create,
44:                 FileAccess.Write,
45:                 FileShare.None,
46:                 bufferSize: 1,
47:                 useAsync: true);
48:             var buffer = new byte[81920];
49:             while (true)
50:             {
51:                 inactivity.CancelAfter(inactivityLimit);
52:                 var read = await source.ReadAsync(buffer, inactivity.Token).ConfigureAwait(false);
53:                 if (read == 0)
54:                     break;
55:                 await target.WriteAsync(buffer.AsMemory(0, read), cancellationToken).ConfigureAwait(false);
56:             }
57:         }
58:         catch (OperationCanceledException) when (inactivity.IsCancellationRequested && !cancellationToken.IsCancellationRequested)
59:         {
60:             throw new TimeoutException($"Download of {url} stopped: no data arrived for {inactivityLimit}.");
61:         }
62:     }
63: }
