3: /// <summary>TR-MCP-NUKE-019: launches a Linux PowerShell logging worker without inheriting the build caller's pipes.</summary>
4: internal static class OllamaDetachedLaunch
5: {
6:     /// <summary>Composes a detached session with all standard handles isolated; the worker writes server output to its log.</summary>
7:     /// <param name="ollamaPath">The executable passed as one literal argument.</param>
8:     /// <param name="logPath">The worker's output file.</param>
9:     /// <param name="workerPath">The checked-in PowerShell worker script.</param>
10:     /// <returns>Start information that retains no caller standard handle.</returns>
11:     internal static ProcessStartInfo CreateLinuxStartInfo(string ollamaPath, string logPath, string workerPath)
12:     {
13:         var info = new ProcessStartInfo
14:         {
15:             FileName = "setsid", UseShellExecute = false, CreateNoWindow = true,
16:             RedirectStandardInput = true, RedirectStandardOutput = true, RedirectStandardError = true,
17:         };
18:         foreach (var argument in new[] { "pwsh.exe", "-NoProfile", "-NonInteractive", "-File", workerPath,
19:                      "-OllamaPath", ollamaPath, "-LogPath", logPath })
20:             info.ArgumentList.Add(argument);
21:         return info;
22:     }
23: 
24:     /// <summary>
25:     /// Starts the logging worker in its own session and releases the parent-side handles without waiting for the
26:     /// long-lived server. The worker sends server output directly to its log, never back through these handles.
27:     /// </summary>
28:     /// <param name="ollamaPath">The server executable.</param>
29:     /// <param name="logPath">The persistent worker log.</param>
30:     /// <param name="workerPath">The PowerShell script used by the worker.</param>
31:     /// <returns>The detached worker's process id.</returns>
32:     internal static int StartLinux(string ollamaPath, string logPath, string workerPath)
33:     {
34:         using var worker = Process.Start(CreateLinuxStartInfo(ollamaPath, logPath, workerPath))
35:             ?? throw new InvalidOperationException("Failed to start the detached Ollama logging worker.");
36:         worker.StandardInput.Close();
37:         return worker.Id;
38:     }
39: }
