111:     /// </summary>
112:     private static string ModelResolve(string workspacePath, string pluginName, string variable, AgentPluginVersionSources sources)
113:     {
114:         foreach (var root in Roots())
115:         {
116:             var version = MarkerFileService.TryReadAgentPluginVersion(root, MarkerFileService.ReadExistingFileText);
117:             if (!string.IsNullOrWhiteSpace(version))
