1: /// <summary>
2: /// TR-MCP-NUKE-019: Production <see cref="IOllamaInstallLayout"/>. The portable release assets are those the
3: /// ollama/ollama releases ship (ollama-windows-amd64.zip with the executable at its root, ollama-linux-amd64.tar.zst
4: /// with the executable under bin/); an installed executable is looked for on PATH first, then in the per-user Windows
5: /// install, then at the portable location.
6: /// </summary>
7: sealed class OllamaInstallLayout : IOllamaInstallLayout
8: {
9:     /// <inheritdoc />
10:     public string ReleaseAsset(IntegrationLaneHost host) => host switch
11:     {
12:         IntegrationLaneHost.Windows => "ollama-windows-amd64.zip",
13:         IntegrationLaneHost.Linux => "ollama-linux-amd64.tar.zst",
14:         _ => throw new ArgumentOutOfRangeException(nameof(host), host, "Unknown integration lane host."),
15:     };
16: 
17:     /// <inheritdoc />
18:     public string PortableExecutable(IntegrationLaneHost host, string testToolsDirectory) => host switch
19:     {
20:         IntegrationLaneHost.Windows => Path.Combine(testToolsDirectory, "ollama", "ollama.exe"),
21:         IntegrationLaneHost.Linux => Path.Combine(testToolsDirectory, "ollama", "bin", "ollama"),
22:         _ => throw new ArgumentOutOfRangeException(nameof(host), host, "Unknown integration lane host."),
23:     };
24: 
25:     /// <inheritdoc />
26:     public IReadOnlyList<string> Candidates(
27:         IntegrationLaneHost host,
28:         IReadOnlyList<string> pathDirectories,
29:         string localApplicationData,
30:         string testToolsDirectory)
31:     {
32:         ArgumentNullException.ThrowIfNull(pathDirectories);
33:         var executableName = host == IntegrationLaneHost.Windows ? "ollama.exe" : "ollama";
34:         var candidates = pathDirectories
35:             .Where(directory => !string.IsNullOrWhiteSpace(directory))
36:             .Select(directory => Path.Combine(directory.Trim(), executableName))
37:             .ToList();
38:         if (host == IntegrationLaneHost.Windows)
39:             candidates.Add(Path.Combine(localApplicationData, "Programs", "Ollama", "ollama.exe"));
40:         candidates.Add(PortableExecutable(host, testToolsDirectory));
41:         return candidates;
42:     }
43: }
